 Capítulo 6 Interpretabilidad de los modelos finales 6.1 Configuración, modelos y partición Los análisis de explicabilidad se realizan después de seleccionar y entrenar los modelos finales. El conjunto de prueba se usa para medir cómo se comportan en observaciones no vistas; el entrenamiento define las medias, desviaciones y datos de referencia. Es imprescindible mantener el mismo corte para ambas respuestas. library(dplyr) library(tidyr) library(ggplot2) library(knitr) library(glmnet) library(yardstick) semilla &lt;- 42 ruta_datos &lt;- &quot;screen_time_mental_health.csv&quot; ruta_split &lt;- &quot;resultados/modelado_libro/split_indices_R.csv&quot; if (!file.exists(ruta_datos)) stop(&quot;Falta el archivo de datos&quot;) if (!file.exists(ruta_split)) { stop(&quot;Primero ejecuta el capítulo 01, que genera split_indices_R.csv&quot;) } df &lt;- read.csv(ruta_datos, stringsAsFactors = FALSE) indices &lt;- read.csv(ruta_split, stringsAsFactors = FALSE) df$sex &lt;- factor(df$sex, levels = c(&quot;Boy&quot;, &quot;Girl&quot;)) df$depressed &lt;- as.integer(as.character(df$depressed)) train &lt;- df[match(indices$subject_id[indices$conjunto == &quot;train&quot;], df$subject_id), ] test &lt;- df[match(indices$subject_id[indices$conjunto == &quot;test&quot;], df$subject_id), ] stopifnot(!anyNA(train$subject_id), !anyNA(test$subject_id)) numericas &lt;- c( &quot;sleep_quality_index&quot;, &quot;avg_sleep_hours&quot;, &quot;midsleep_weekend_hours&quot;, &quot;social_jetlag_hours&quot;, &quot;screen_time_index&quot; ) predictores &lt;- c(numericas, &quot;sex&quot;) medias_train &lt;- vapply(train[, numericas, drop = FALSE], mean, numeric(1)) desvios_train &lt;- vapply(train[, numericas, drop = FALSE], sd, numeric(1)) stopifnot(all(desvios_train &gt; 0)) X_train_num &lt;- scale(as.matrix(train[, numericas, drop = FALSE]), center = medias_train, scale = desvios_train) X_test_num &lt;- scale(as.matrix(test[, numericas, drop = FALSE]), center = medias_train, scale = desvios_train) X_train &lt;- cbind(X_train_num, sex_Girl = as.integer(train$sex == &quot;Girl&quot;)) X_test &lt;- cbind(X_test_num, sex_Girl = as.integer(test$sex == &quot;Girl&quot;)) stopifnot(identical(colnames(X_train), colnames(X_test))) kable(data.frame(Variable = colnames(X_train), Tipo = c(rep(&quot;Estandarizada&quot;, 5), &quot;Binaria: chica=1&quot;))) Variable Tipo sleep_quality_index Estandarizada avg_sleep_hours Estandarizada midsleep_weekend_hours Estandarizada social_jetlag_hours Estandarizada screen_time_index Estandarizada sex_Girl Binaria: chica=1 6.1.1 ElasticNet y CatBoost finales para el ejemplo El ElasticNet se interpreta mediante sus coeficientes y SHAP lineal. En clasificación se utiliza CatBoost, que permite calcular importancia nativa y valores SHAP del ensamble. Los hiperparámetros de abajo son demostrativos: no se seleccionan aquí usando el test, y no equivalen automáticamente a los mejores parámetros obtenidos en Python. alpha_final &lt;- 0.5 lambda_final &lt;- 0.01 elasticnet_final &lt;- glmnet::glmnet( x = X_train, y = train$bdi_total, family = &quot;gaussian&quot;, alpha = alpha_final, lambda = lambda_final, standardize = FALSE ) pred_elastic_sin_recorte &lt;- as.numeric( predict(elasticnet_final, newx = X_test, s = lambda_final) ) pred_elastic &lt;- pmax(0, pmin(63, pred_elastic_sin_recorte)) coeficientes_en &lt;- as.matrix(coef(elasticnet_final, s = lambda_final)) coeficientes_en ## s=0.01 ## (Intercept) 5.69679704 ## sleep_quality_index 2.15795193 ## avg_sleep_hours -0.75375150 ## midsleep_weekend_hours 0.38064847 ## social_jetlag_hours 0.07436213 ## screen_time_index 0.50451658 ## sex_Girl 3.18079291 set.seed(semilla) pool_train &lt;- catboost::catboost.load_pool( data = X_train, label = train$depressed ) pool_test &lt;- catboost::catboost.load_pool( data = X_test, label = test$depressed ) catboost_final &lt;- catboost::catboost.train( learn_pool = pool_train, params = list( loss_function = &quot;Logloss&quot;, iterations = 500, depth = 3, learning_rate = 0.03, l2_leaf_reg = 4, auto_class_weights = &quot;Balanced&quot;, random_seed = semilla, thread_count = 2, verbose = FALSE ) ) prob_catboost &lt;- as.numeric(catboost::catboost.predict( catboost_final, pool_test, prediction_type = &quot;Probability&quot; )) 6.2 Coeficientes del ElasticNet Para variables estandarizadas, un coeficiente expresa el cambio estimado de BDI-II asociado a una desviación estándar del predictor, manteniendo constantes las demás variables. Para sex_Girl, expresa el contraste entre chicas y chicos. El efecto por unidad original se obtiene dividiendo el coeficiente numérico por la desviación del predictor en entrenamiento; la categoría binaria no se divide. tabla_coeficientes &lt;- data.frame( Variable = rownames(coeficientes_en)[-1], Coeficiente_por_DE = as.numeric(coeficientes_en[-1, 1]) ) tabla_coeficientes$Efecto_por_unidad &lt;- tabla_coeficientes$Coeficiente_por_DE for (j in numericas) { tabla_coeficientes$Efecto_por_unidad[ tabla_coeficientes$Variable == j ] &lt;- tabla_coeficientes$Coeficiente_por_DE[ tabla_coeficientes$Variable == j ] / desvios_train[j] } tabla_coeficientes$En_cero &lt;- abs(tabla_coeficientes$Coeficiente_por_DE) &lt; 1e-8 kable(tabla_coeficientes, digits = 3) Variable Coeficiente_por_DE Efecto_por_unidad En_cero sleep_quality_index 2.158 2.535 FALSE avg_sleep_hours -0.754 -0.591 FALSE midsleep_weekend_hours 0.381 0.268 FALSE social_jetlag_hours 0.074 0.065 FALSE screen_time_index 0.505 0.490 FALSE sex_Girl 3.181 3.181 FALSE ggplot(tabla_coeficientes, aes(x = reorder(Variable, Coeficiente_por_DE), y = Coeficiente_por_DE, fill = Coeficiente_por_DE &gt; 0)) + geom_col(width = 0.65) + coord_flip() + geom_hline(yintercept = 0, linewidth = 0.4) + scale_fill_manual(values = c(&quot;#A3C3E5&quot;, &quot;#EFAC91&quot;), guide = &quot;none&quot;) + labs(title = &quot;ElasticNet: coeficientes estandarizados&quot;, x = NULL, y = &quot;Cambio estimado en puntos BDI-II&quot;) + theme_minimal(base_size = 12) Un coeficiente igual a cero puede reflejar selección de variables por la componente L1. Su anulación o magnitud depende del lambda y alpha elegidos; no debe afirmarse que un predictor carece de asociación causal. 6.3 Importancia nativa de CatBoost Se calculan dos medidas: PredictionValuesChange, asociada al cambio de la salida del modelo, y LossFunctionChange, que refleja cuánto se deteriora su función de pérdida al retirar información de la variable. Ninguna ofrece por sí sola la dirección de los efectos. Las variables correlacionadas pueden repartirse la importancia. imp_pvc &lt;- as.numeric(catboost::catboost.get_feature_importance( catboost_final, pool = pool_test, type = &quot;PredictionValuesChange&quot; )) imp_lfc &lt;- as.numeric(catboost::catboost.get_feature_importance( catboost_final, pool = pool_test, type = &quot;LossFunctionChange&quot; )) importancias_catboost &lt;- data.frame( Variable = colnames(X_test), PredictionValuesChange = imp_pvc, LossFunctionChange = imp_lfc ) kable(importancias_catboost, digits = 4) importancias_catboost %&gt;% pivot_longer(-Variable, names_to = &quot;Metodo&quot;, values_to = &quot;Importancia&quot;) %&gt;% ggplot(aes(x = reorder(Variable, Importancia), y = Importancia)) + geom_col(fill = &quot;#A3C3E5&quot;) + coord_flip() + facet_wrap(~Metodo, scales = &quot;free_x&quot;) + labs(title = &quot;CatBoost: medidas nativas de importancia&quot;, x = NULL, y = &quot;Importancia&quot;) + theme_minimal(base_size = 12) 6.4 SHAP: explicación global y local Para cada observación, SHAP descompone la salida del modelo como suma de un valor base y contribuciones de las variables. En CatBoost binario, la descomposición habitual corresponde a la escala de log-odds; al aplicar la función logística se obtiene la probabilidad. En ElasticNet los aportes son en puntos BDI-II antes de recortar al rango [0, 63]. Por eso no deben compararse numéricamente las escalas de ambos modelos. \[ f(x_i) = \phi_0 + \sum_{j=1}^{p} \phi_{ij}. \] 6.4.1 SHAP lineal exacto para ElasticNet En un modelo lineal con datos de referencia del train, la contribución de la variable \(j\) es el coeficiente multiplicado por la diferencia entre la observación y la media de referencia: \[ \phi_{ij}= eta_j(x_{ij}-\overline{x}_{j,\mathrm{train}}). \] betas &lt;- as.numeric(coeficientes_en[-1, 1]) intercepto &lt;- as.numeric(coeficientes_en[1, 1]) medias_X &lt;- colMeans(X_train) base_en &lt;- intercepto + sum(medias_X * betas) X_centrado &lt;- sweep(X_test, 2, medias_X, &quot;-&quot;) shap_en &lt;- sweep(X_centrado, 2, betas, &quot;*&quot;) colnames(shap_en) &lt;- colnames(X_test) reconstruido_en &lt;- base_en + rowSums(shap_en) error_aditividad_en &lt;- max(abs(reconstruido_en - pred_elastic_sin_recorte)) cat(&quot;Base ElasticNet:&quot;, round(base_en, 4), &quot;puntos BDI
&quot;) ## Base ElasticNet: 7.2628 puntos BDI cat(&quot;Error máximo de aditividad:&quot;, signif(error_aditividad_en, 4), &quot;
&quot;) ## Error máximo de aditividad: 3.553e-15 shap_global_en &lt;- data.frame( Variable = colnames(shap_en), Media_abs_SHAP = colMeans(abs(shap_en)) ) ggplot(shap_global_en, aes(x = reorder(Variable, Media_abs_SHAP), y = Media_abs_SHAP)) + geom_col(fill = &quot;#D6A5C3&quot;) + coord_flip() + labs(title = &quot;ElasticNet: importancia global SHAP&quot;, x = NULL, y = &quot;Media del valor absoluto de SHAP (puntos BDI)&quot;) + theme_minimal(base_size = 12) 6.4.2 SHAP de CatBoost y prueba de aditividad CatBoost ofrece valores SHAP nativos. La última columna contiene el valor base. Su suma debe reconstruir la salida RawFormulaVal, no la probabilidad directamente. shap_cb_completo &lt;- as.matrix(catboost::catboost.get_feature_importance( catboost_final, pool = pool_test, type = &quot;ShapValues&quot; )) shap_cb &lt;- shap_cb_completo[, seq_len(ncol(X_test)), drop = FALSE] colnames(shap_cb) &lt;- colnames(X_test) base_cb &lt;- shap_cb_completo[, ncol(shap_cb_completo)] raw_cb &lt;- as.numeric(catboost::catboost.predict( catboost_final, pool_test, prediction_type = &quot;RawFormulaVal&quot; )) error_aditividad_cb &lt;- max(abs(base_cb + rowSums(shap_cb) - raw_cb)) cat(&quot;Error máximo SHAP CatBoost:&quot;, signif(error_aditividad_cb, 4), &quot;
&quot;) shap_global_cb &lt;- data.frame( Variable = colnames(shap_cb), Media_abs_SHAP = colMeans(abs(shap_cb)) ) kable(shap_global_cb, digits = 4) ggplot(shap_global_cb, aes(x = reorder(Variable, Media_abs_SHAP), y = Media_abs_SHAP)) + geom_col(fill = &quot;#EFAC91&quot;) + coord_flip() + labs(title = &quot;CatBoost: importancia SHAP global&quot;, x = NULL, y = &quot;Media |SHAP| (log-odds)&quot;) + theme_minimal(base_size = 12) 6.4.3 Distribuciones de SHAP (beeswarm simplificado) El conjunto de puntos permite observar signo, magnitud y heterogeneidad. En estos gráficos se utiliza jitter para evitar el solapamiento; no es idéntico al algoritmo de colocación beeswarm de Python. shap_en_largo &lt;- as.data.frame(shap_en) %&gt;% mutate(Fila = row_number()) %&gt;% pivot_longer(-Fila, names_to = &quot;Variable&quot;, values_to = &quot;SHAP&quot;) valores_originales &lt;- as.data.frame(X_test) %&gt;% mutate(Fila = row_number()) %&gt;% pivot_longer(-Fila, names_to = &quot;Variable&quot;, values_to = &quot;Valor&quot;) shap_en_largo &lt;- left_join(shap_en_largo, valores_originales, by = c(&quot;Fila&quot;, &quot;Variable&quot;)) ggplot(shap_en_largo, aes(x = SHAP, y = Variable, color = Valor)) + geom_jitter(height = 0.18, width = 0, alpha = 0.45, size = 1) + scale_color_gradient(low = &quot;#A3C3E5&quot;, high = &quot;#EFAC91&quot;) + labs(title = &quot;ElasticNet: contribuciones SHAP individuales&quot;, x = &quot;SHAP (puntos BDI)&quot;, y = NULL, color = &quot;Valor
transformado&quot;) + theme_minimal(base_size = 12) shap_cb_largo &lt;- as.data.frame(shap_cb) %&gt;% mutate(Fila = row_number()) %&gt;% pivot_longer(-Fila, names_to = &quot;Variable&quot;, values_to = &quot;SHAP&quot;) %&gt;% left_join(valores_originales, by = c(&quot;Fila&quot;, &quot;Variable&quot;)) ggplot(shap_cb_largo, aes(x = SHAP, y = Variable, color = Valor)) + geom_jitter(height = 0.18, width = 0, alpha = 0.45, size = 1) + scale_color_gradient(low = &quot;#A3C3E5&quot;, high = &quot;#EFAC91&quot;) + labs(title = &quot;CatBoost: contribuciones SHAP individuales&quot;, x = &quot;SHAP (log-odds)&quot;, y = NULL, color = &quot;Valor
transformado&quot;) + theme_minimal(base_size = 12) 6.4.4 Explicación individual y gráfico de contribuciones Para ilustrar un caso del test, el modelo parte de su valor base y suma efectos positivos o negativos. Una contribución positiva aumenta el puntaje BDI del ElasticNet o los log-odds del CatBoost; no es una afirmación causal. posicion &lt;- 1 explicacion_en &lt;- data.frame( Variable = colnames(shap_en), Contribucion = as.numeric(shap_en[posicion, ]) ) cat(&quot;Sujeto:&quot;, test$subject_id[posicion], &quot;
&quot;) ## Sujeto: 6 cat(&quot;Base:&quot;, round(base_en, 2), &quot;
&quot;) ## Base: 7.26 cat(&quot;Predicción lineal:&quot;, round(reconstruido_en[posicion], 2), &quot;
&quot;) ## Predicción lineal: 2.32 ggplot(explicacion_en, aes(x = reorder(Variable, Contribucion), y = Contribucion, fill = Contribucion &gt; 0)) + geom_col() + coord_flip() + scale_fill_manual(values = c(&quot;#A3C3E5&quot;, &quot;#EFAC91&quot;), guide = &quot;none&quot;) + labs(title = &quot;ElasticNet: aportes SHAP de una observación&quot;, subtitle = &quot;Las barras suman la diferencia frente al valor base&quot;, x = NULL, y = &quot;Contribución (puntos BDI)&quot;) + theme_minimal(base_size = 12) 6.4.5 Dependencia y posibles no linealidades En CatBoost, los gráficos de dependencia comparan el valor original de una variable con su contribución SHAP, coloreada por sexo. Sirven para investigar cambios de pendiente, umbrales e interacciones. No implican una relación causal. variable_interes &lt;- &quot;sleep_quality_index&quot; dependencia_cb &lt;- data.frame( Valor_original = test[[variable_interes]], SHAP = shap_cb[, variable_interes], Sexo = test$sex ) ggplot(dependencia_cb, aes(x = Valor_original, y = SHAP, color = Sexo)) + geom_point(alpha = 0.55, size = 1.6) + geom_smooth(se = FALSE, method = &quot;loess&quot;, linewidth = 0.8) + scale_color_manual(values = c(Boy = &quot;#9AC7BD&quot;, Girl = &quot;#D6A5C3&quot;)) + labs(title = &quot;CatBoost: dependencia SHAP de calidad del sueño&quot;, x = &quot;Índice de calidad del sueño&quot;, y = &quot;SHAP (log-odds)&quot;) + theme_minimal(base_size = 12) 6.5 LIME: explicaciones locales LIME aproxima localmente las predicciones de un modelo con una regresión interpretable ajustada sobre observaciones perturbadas. En R el paquete lime necesita conocer cómo obtener la predicción de un objeto. Para glmnet y el modelo CatBoost mostrado aquí se requieren pequeños métodos de adaptación; por eso, a diferencia de las transformaciones estadísticas anteriores, este bloque sí declara métodos S3. library(lime) modelo_lime_en &lt;- structure( list(modelo = elasticnet_final, tipo = &quot;regression&quot;, numericas = numericas, medias = medias_train, desvios = desvios_train, lambda = lambda_final), class = &quot;modelo_lime_libro&quot; ) model_type.modelo_lime_libro &lt;- function(x, ...) x$tipo predict_model.modelo_lime_libro &lt;- function(x, newdata, type, ...) { mat_num &lt;- scale(as.matrix(newdata[, x$numericas, drop = FALSE]), center = x$medias, scale = x$desvios) mat &lt;- cbind(mat_num, sex_Girl = as.integer(as.character(newdata$sex) == &quot;Girl&quot;)) yhat &lt;- as.numeric(predict(x$model, newx = mat, s = x$lambda)) data.frame(Response = pmax(0, pmin(63, yhat))) } set.seed(semilla) expl_lime_en &lt;- lime::lime(train[, predictores], modelo_lime_en) casos_en &lt;- test[c(1, 2, 3), predictores] explicaciones_lime &lt;- lime::explain( casos_en, expl_lime_en, n_features = 6, n_permutations = 5000 ) lime::plot_features(explicaciones_lime) En el original se interpretan tres perfiles de clasificación (verdadero positivo, falso negativo y falso positivo) y tres de regresión (BDI bajo, cercano a 14 y alto). Para replicar esa selección, se debe calcular primero la predicción de todo el test y utilizar el umbral elegido con el train, no un umbral improvisado durante la interpretación. 6.5.1 LIME frente a SHAP Los métodos tienen objetivos distintos. SHAP distribuye la salida del modelo respecto de una referencia global; LIME aproxima el comportamiento del modelo cerca de un caso. Conviene contrastar el signo y el orden de las principales variables, pero no comparar directamente coeficientes en probabilidad con valores SHAP en log-odds. 6.6 Importancia por permutación del ElasticNet La importancia por permutación mide cuánto empeora el RMSE al desordenar una variable del test. Aquí se realizan 30 permutaciones para cada predictor, manteniendo el modelo fijo. Es una medida de dependencia predictiva, no de causalidad; la correlación entre variables puede reducir la importancia individual. set.seed(42) rmse_base &lt;- sqrt(mean((test$bdi_total - pred_elastic)^2)) permutaciones &lt;- data.frame( Variable = predictores, Aumento_RMSE = NA_real_, DE = NA_real_ ) for (j in seq_along(predictores)) { variable &lt;- predictores[j] aumentos &lt;- numeric(30) for (b in 1:30) { test_permutado &lt;- test test_permutado[[variable]] &lt;- sample(test_permutado[[variable]]) num_perm &lt;- scale(as.matrix(test_permutado[, numericas, drop = FALSE]), center = medias_train, scale = desvios_train) X_perm &lt;- cbind(num_perm, sex_Girl = as.integer(test_permutado$sex == &quot;Girl&quot;)) pred_perm &lt;- as.numeric(predict( elasticnet_final, newx = X_perm, s = lambda_final )) pred_perm &lt;- pmax(0, pmin(63, pred_perm)) rmse_perm &lt;- sqrt(mean((test$bdi_total - pred_perm)^2)) aumentos[b] &lt;- rmse_perm - rmse_base } permutaciones$Aumento_RMSE[j] &lt;- mean(aumentos) permutaciones$DE[j] &lt;- sd(aumentos) } permutaciones &lt;- permutaciones %&gt;% arrange(desc(Aumento_RMSE)) kable(permutaciones, digits = 4) Variable Aumento_RMSE DE sleep_quality_index 0.7913 0.0638 sex 0.3845 0.0497 avg_sleep_hours 0.1436 0.0235 screen_time_index 0.0359 0.0130 midsleep_weekend_hours 0.0278 0.0118 social_jetlag_hours 0.0013 0.0021 ggplot(permutaciones, aes(x = reorder(Variable, Aumento_RMSE), y = Aumento_RMSE)) + geom_col(fill = &quot;#A3C3E5&quot;, width = 0.65) + geom_errorbar(aes(ymin = Aumento_RMSE - DE, ymax = Aumento_RMSE + DE), width = 0.15) + coord_flip() + labs(title = &quot;ElasticNet: importancia por permutación (30 repeticiones)&quot;, x = NULL, y = &quot;Aumento del RMSE (puntos BDI)&quot;) + theme_minimal(base_size = 12) 6.7 Guardado y reproducibilidad Para conservar los resultados de R se exportan coeficientes, SHAP global del ElasticNet e importancia por permutación. Si CatBoost está instalado, también pueden exportarse sus medidas; los valores no deben sustituirse por los publicados en Python. dir.create(&quot;resultados/modelado_libro/interpretabilidad&quot;, recursive = TRUE, showWarnings = FALSE) write.csv(tabla_coeficientes, &quot;resultados/modelado_libro/interpretabilidad/coeficientes_elasticnet.csv&quot;, row.names = FALSE) write.csv(shap_global_en, &quot;resultados/modelado_libro/interpretabilidad/shap_global_elasticnet.csv&quot;, row.names = FALSE) write.csv(permutaciones, &quot;resultados/modelado_libro/interpretabilidad/permutacion_elasticnet.csv&quot;, row.names = FALSE) saveRDS( list(modelo_elasticnet = elasticnet_final, medias = medias_train, desvios = desvios_train, variables = colnames(X_train), lambda = lambda_final, alpha = alpha_final), &quot;resultados/modelado_libro/interpretabilidad/elasticnet_R.rds&quot; ) write.csv(importancias_catboost, &quot;resultados/modelado_libro/interpretabilidad/importancia_catboost.csv&quot;, row.names = FALSE) write.csv(shap_global_cb, &quot;resultados/modelado_libro/interpretabilidad/shap_global_catboost.csv&quot;, row.names = FALSE) catboost::catboost.save_model( catboost_final, &quot;resultados/modelado_libro/interpretabilidad/catboost_R.cbm&quot; ) 6.8 Interpretación de resultados En el libro original, la calidad del sueño y el sexo aparecen entre los predictores más relevantes, seguidos de la duración del sueño. Los valores SHAP del clasificador CatBoost se expresan en log-odds, mientras que las contribuciones del ElasticNet se presentan en puntos BDI-II. El análisis describe asociaciones utilizadas por los modelos, sin inferir que alterar una variable produciría necesariamente el cambio predicho. Los resultados de esta adaptación deben comentarse después de ejecutar los bloques en R, porque la variabilidad en el split, la regularización y el entrenamiento puede cambiar las magnitudes y el orden de las variables. No se deben reutilizar literalmente como resultados de R los coeficientes o las importancias estimadas en Python.
